  async ensureSession(actor:string,token:string,userAgent:string){const tokenHash=hash(token),key=`session:${tokenHash.slice(0,40)}`,existing=await this.repo.getProductObject(key),now=this.now().toISOString();if(existing?.payload.revoked)throw new DomainError('session_revoked','This device session was revoked',401);const value:ProductObject=existing?{...existing,payload:{...existing.payload,lastSeenAt:now},updatedAt:now}:{id:key,objectType:'session',ownerAccount:actor,visibility:'private',payload:{tokenHash,userAgent:clean(userAgent,240)||'Unknown device',createdAt:now,lastSeenAt:now,revoked:false},createdAt:now,updatedAt:now};await this.repo.putProductObject(value);return value.id;}
  async sessions(actor:string,currentToken?:string){const currentId=currentToken?`session:${hash(currentToken).slice(0,40)}`:'';return (await this.repo.listProductObjects('session')).filter(v=>v.ownerAccount===actor).map(v=>({id:v.id,userAgent:v.payload.userAgent,createdAt:v.createdAt,lastSeenAt:v.payload.lastSeenAt,revoked:!!v.payload.revoked,current:v.id===currentId}));}
  async revokeSession(actor:string,sessionId:string){const value=await this.repo.getProductObject(sessionId);if(!value||value.objectType!=='session'||value.ownerAccount!==actor)throw new DomainError('not_found','Session not found',404);value.payload={...value.payload,revoked:true,revokedAt:this.now().toISOString()};value.updatedAt=this.now().toISOString();await this.repo.putProductObject(value);await this.audit(actor,'session.revoked',{sessionId});return {id:sessionId,revoked:true};}
  async toggleBlock(actor:string,target:string){if(actor===target)throw new DomainError('invalid_block','You cannot block yourself');const key=`block:${actor}:${target}`,existing=await this.repo.getProductObject(key);if(existing){await this.repo.deleteProductObject(key);await this.audit(actor,'account.unblocked',{target});return {blocked:false};}const now=this.now().toISOString();await this.repo.putProductObject({id:key,objectType:'block',ownerAccount:actor,visibility:'private',payload:{target},createdAt:now,updatedAt:now});await this.repo.deleteProductObject(`follow:${actor}:${target}`);await this.repo.deleteProductObject(`follow:${target}:${actor}`);await this.audit(actor,'account.blocked',{target});return {blocked:true};}
  async report(actor:string,input:any){const targetType=clean(input?.targetType,20),targetId=clean(input?.targetId,120),reason=clean(input?.reason,500);if(!['profile','strategy','comment'].includes(targetType)||!targetId||reason.length<5)throw new DomainError('invalid_report','Choose a valid target and explain the report');const now=this.now().toISOString(),value:ProductObject={id:id('report'),objectType:'report',ownerAccount:actor,strategyId:targetType==='strategy'?targetId:undefined,visibility:'private',payload:{targetType,targetId,reason,status:'open'},createdAt:now,updatedAt:now};await this.repo.putProductObject(value);await this.audit(actor,'report.created',{targetType,targetId});return {id:value.id,status:'open'};}
