  async resolveReport(actor:string,idValue:string,input:any){this.requireAdmin(actor);const value=await this.repo.getProductObject(idValue),status=clean(input?.status,20);if(!value||value.objectType!=='report')throw new DomainError('not_found','Report not found',404);if(!['reviewing','resolved','dismissed'].includes(status))throw new DomainError('invalid_status','Use reviewing, resolved, or dismissed');value.payload={...value.payload,status,moderator:actor,note:clean(input?.note??'',500),resolvedAt:this.now().toISOString()};value.updatedAt=this.now().toISOString();await this.repo.putProductObject(value);await this.audit(actor,'report.moderated',{reportId:idValue,status});return {id:idValue,status};}
