  async toggleFollow(actor:string,target:string){await this.requireProfile(actor);if(actor===target)throw new DomainError('invalid_follow','You cannot follow yourself');if(!await this.repo.getProfile(target))throw new DomainError('not_found','Profile not found',404);const key=`follow:${actor}:${target}`,existing=await this.repo.getProductObject(key);if(existing){await this.repo.deleteProductObject(key);return {following:false};}const now=this.now().toISOString();await this.repo.putProductObject({id:key,objectType:'follow',ownerAccount:actor,visibility:'public',payload:{target},createdAt:now,updatedAt:now});await this.notify(target,actor,'follow',undefined,`${actor} followed you`);return {following:true};}
  async toggleLike(actor:string,strategyId:string){await this.requireProfile(actor);const strategy=await this.repo.getStrategy(strategyId);if(!strategy)throw new DomainError('not_found','Strategy not found',404);const key=`like:${actor}:${strategyId}`,existing=await this.repo.getProductObject(key);if(existing){await this.repo.deleteProductObject(key);return {liked:false};}const now=this.now().toISOString();await this.repo.putProductObject({id:key,objectType:'like',ownerAccount:actor,strategyId,visibility:'public',payload:{},createdAt:now,updatedAt:now});if(strategy.owner!==actor)await this.notify(strategy.owner,actor,'like',strategyId,`${actor} liked ${strategy.name}`);return {liked:true};}
  async comments(strategyId:string){if(!await this.repo.getStrategy(strategyId))throw new DomainError('not_found','Strategy not found',404);const values=(await this.repo.listProductObjects('comment')).filter(v=>v.strategyId===strategyId);return Promise.all(values.map(async v=>({...v.payload,id:v.id,author:v.ownerAccount,createdAt:v.createdAt,profile:await this.repo.getProfile(v.ownerAccount)})));}
  async addComment(actor:string,strategyId:string,input:any){await this.requireProfile(actor);const strategy=await this.repo.getStrategy(strategyId);if(!strategy)throw new DomainError('not_found','Strategy not found',404);const body=clean(input?.body,500);if(!body)throw new DomainError('invalid_comment','Comment cannot be empty');const now=this.now().toISOString(),value:ProductObject={id:id('comment'),objectType:'comment',ownerAccount:actor,strategyId,visibility:'public',payload:{body},createdAt:now,updatedAt:now};await this.repo.putProductObject(value);if(strategy.owner!==actor)await this.notify(strategy.owner,actor,'comment',strategyId,`${actor} commented on ${strategy.name}`);return {...value.payload,id:value.id,author:actor,createdAt:now,profile:await this.repo.getProfile(actor)};}
